mapper.select:
SELECT id, merchant_id, sku_id, biz_type, biz_id,
       change_available, change_reserved,
       before_available, after_available,
       before_reserved, after_reserved,
       idempotent_key, operator_id, remark, create_time
FROM inventory_transaction
WHERE merchant_id = #{merchantId}
  AND sku_id = #{skuId}
ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}
